using System;using System.IO;using System.Drawing;using System.Windows.Forms;
internal sealed partial class Studio{
 SmartColors pendingSmart;bool pendingSmartRestore;
 void ChooseSmartPalette(){try{string source=backgroundSource??AutoBackground.SavedImage();if(source==null)throw new IOException("请先在壁纸页面选择一张图片。");using(var dialog=new SmartPaletteDialog(source))if(dialog.ShowDialog(this)==DialogResult.OK){pendingTransfer=null;pendingSmart=dialog.Value;for(int i=0;i<16;i++)if(i%2!=pendingSmart.RuntimeMode)pendingSmart.Theme.Colors[i]=current.Colors[i];pendingSmartRestore=false;SelectTheme(pendingSmart.Theme);ChangeEditingAppearance(pendingSmart.RuntimeMode);mode.SelectedIndex=pendingSmart.RuntimeMode;StageVisualSmartRuntime();SelectWorkspace("palette");status.Text="智能方案已载入，尚未修改微信。连接预览后点「应用基础配色」；未连接时需先退出微信。";}}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}}
 void StageSmartRestore(){try{if(!SmartPalette.HasBackup)throw new IOException("尚无智能取色备份；第一次应用方案时会自动保存。");pendingTransfer=null;pendingSmart=null;pendingSmartRestore=true;SelectTheme(SmartPalette.BackupTheme());SelectWorkspace("palette");status.Text="已载入取色前的配色；退出微信后应用，届时同时恢复原文字和图标设置。";}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}}
 void ValidateSmartDraft(Theme theme){if(pendingSmart==null||!pendingSmart.IncludeRuntime)return;var text=ColorTranslator.FromHtml(pendingSmart.Text);for(int i=10+pendingSmart.RuntimeMode;i<16;i+=2)if(SmartPalette.Contrast(i==10+pendingSmart.RuntimeMode?ColorTranslator.FromHtml(SmartPalette.SelectionInk(theme,pendingSmart.RuntimeMode,pendingSmart.Text)):text,ColorTranslator.FromHtml(theme.Colors[i]))<4.5)throw new IOException("当前选中行或气泡与方案文字的对比度不足。请调暗这些底色，或重新生成方案。");}
 void PrepareSmartBackup(bool restoring){if(!restoring&&pendingSmart!=null)SmartPalette.Backup();}
 void CommitSmartDraft(bool restoring){if(restoring){pendingTransfer=null;pendingSmart=null;pendingSmartRestore=false;return;}if(pendingTransfer!=null){ThemeTransfer.Commit(pendingTransfer,!(nativeFlowBusy||NativePreviewBridge.Connected||NativeBackground.InternalModulePresent()));pendingTransfer=null;status.Text="迁移设置已应用，自动后台已启用；请正常启动微信。";RefreshSmartForms();return;}if(pendingSmartRestore){SmartPalette.RestoreConfig();pendingSmartRestore=false;status.Text="已恢复智能取色前的基础配色和运行时颜色。";}else if(pendingSmart!=null){SmartPalette.Commit(pendingSmart);if(pendingSmart.IncludeRuntime&&!NativePreviewBridge.Connected&&!NativeBackground.InternalModulePresent())AutoBackground.SetEnabled(true);pendingSmart=null;status.Text="整套智能配色已保存，后台已就绪；正常启动微信即可。";}RefreshSmartForms();}
 void RefreshSmartForms(){if(workspaceInk!=null){workspaceForms.Remove(workspaceInk);workspaceInk.Dispose();workspaceInk=null;workspacePages["messages"].Controls.Clear();}if(workspaceIcons!=null){workspaceForms.Remove(workspaceIcons);workspaceIcons.Dispose();workspaceIcons=null;workspacePages["icons"].Controls.Clear();}if(workspaceInput!=null){workspaceForms.Remove(workspaceInput);workspaceInput.Dispose();workspaceInput=null;workspacePages["input"].Controls.Clear();}if(workspaceEffects!=null){workspaceForms.Remove(workspaceEffects);workspaceEffects.Dispose();workspaceEffects=null;}EnsureWorkspaceForm(workspacePage);}
}
